export const getBabyProductsProducts = (): Product[] => BABY_PRODUCTS_PRODUCTS;

export const getFeaturedBabyProductsProducts = (): Product[] => 
  BABY_PRODUCTS_PRODUCTS.filter(product => product.featured);

export const getBabyProductsProductsByBadge = (badge: string): Product[] =>
  BABY_PRODUCTS_PRODUCTS.filter(product => product.badge === badge);

export const getBabyProductsProductsByPriceRange = (min: number, max: number): Product[] =>
  BABY_PRODUCTS_PRODUCTS.filter(product => product.price >= min && product.price <= max);
